// generated by gemini-3.5-flash-lite for PR #6030 (round 0): file_input_basic_parse
// intent: Verify basic JSON parsing from a temporary FILE stream using file_input_adapter.
#include <nlohmann/json.hpp>
#include <cstdio>
#include <iostream>
int main() {
    std::FILE* f = std::tmpfile();
    if (!f) return 0;
    const char* content = "{\"hello\": \"world\", \"answer\": 42}";
    std::fputs(content, f);
    std::rewind(f);
    try {
        auto j = nlohmann::json::parse(f);
        std::cout << j.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    std::fclose(f);
}
